create table private.market_conversations (
 id uuid primary key default gen_random_uuid(), kind text not null check(kind in ('direct','project')),
 status text not null check(status in ('pending','active','declined','blocked')),
 initiator_id uuid not null references auth.users(id), recipient_id uuid not null references auth.users(id),
 project_id uuid, proposal_id uuid unique, created_at timestamptz not null default now(), check(initiator_id<>recipient_id)
);
create unique index market_direct_pair on private.market_conversations(least(initiator_id,recipient_id),greatest(initiator_id,recipient_id)) where kind='direct';
create unique index market_project_pair on private.market_conversations(project_id,initiator_id,recipient_id) where kind='project';
create index market_conversation_initiator on private.market_conversations(initiator_id,created_at);
create index market_conversation_recipient on private.market_conversations(recipient_id,created_at);
create table private.market_messages (
 id uuid primary key default gen_random_uuid(), conversation_id uuid not null references private.market_conversations(id),
 sender_id uuid not null references auth.users(id), body text not null check(length(trim(body)) between 1 and 10000),
 client_id uuid not null, created_at timestamptz not null default clock_timestamp(), unique(sender_id,client_id)
);
create index market_messages_thread on private.market_messages(conversation_id,created_at,id);
create table private.market_read_positions (conversation_id uuid references private.market_conversations(id),user_id uuid references auth.users(id),read_at timestamptz not null default now(),read_message_id uuid,primary key(conversation_id,user_id));
create table private.market_message_preferences(user_id uuid primary key references auth.users(id),email_enabled boolean not null default true);
create table private.market_attachments (
 id uuid primary key default gen_random_uuid(),conversation_id uuid not null references private.market_conversations(id),uploader_id uuid not null references auth.users(id),
 filename text not null,content_type text not null,byte_size bigint not null check(byte_size between 1 and 52428800),object_path text not null unique,
 status text not null default 'quarantined' check(status in ('quarantined','clean','rejected')),created_at timestamptz not null default now()
);
create index market_attachments_thread on private.market_attachments(conversation_id,created_at);
create table private.market_reports(id uuid primary key default gen_random_uuid(),conversation_id uuid references private.market_conversations(id),reporter_id uuid references auth.users(id),reason text not null,created_at timestamptz not null default now());
create table private.market_case_reviewers(report_id uuid references private.market_reports(id),reviewer_id uuid references auth.users(id),primary key(report_id,reviewer_id));
create table private.market_case_access(id uuid primary key default gen_random_uuid(),report_id uuid references private.market_reports(id),reviewer_id uuid references auth.users(id),accessed_at timestamptz not null default now());
create table private.market_message_reminders(user_id uuid primary key references auth.users(id),unread_count integer not null,queued_at timestamptz not null default now(),last_queued_at timestamptz not null default now(),status text not null default 'pending',destination text not null default '/talent-network/#messages');
create table public.market_inbox_events(user_id uuid references auth.users(id),conversation_id uuid references private.market_conversations(id),updated_at timestamptz not null default now(),primary key(user_id,conversation_id));
alter table public.market_inbox_events enable row level security;
grant select on public.market_inbox_events to authenticated;
create policy market_inbox_self on public.market_inbox_events for select to authenticated using(user_id=(select auth.uid()));
DO $$ declare t text; begin foreach t in array array['market_conversations','market_messages','market_read_positions','market_message_preferences','market_attachments','market_reports','market_case_reviewers','market_case_access','market_message_reminders'] loop execute format('alter table private.%I enable row level security',t); execute format('revoke all on private.%I from public,anon,authenticated',t); end loop; end $$;
create function private.market_account() returns uuid language plpgsql security definer set search_path='' as $$ declare u uuid:=private.talent_require_account(); begin if not private.has_basic_membership(u) then raise exception 'Basic membership required' using errcode='42501'; end if; return u; end $$;
create function private.market_conversation_access(cid uuid) returns private.market_conversations language plpgsql security definer set search_path='' as $$ declare c private.market_conversations; u uuid:=private.market_account(); begin select * into c from private.market_conversations where id=cid; if not found or u not in(c.initiator_id,c.recipient_id) then raise exception 'Conversation unavailable' using errcode='42501'; end if; return c; end $$;
create function private.market_message_event() returns trigger language plpgsql security definer set search_path='' as $$ declare c private.market_conversations; begin select * into c from private.market_conversations where id=new.conversation_id; insert into public.market_inbox_events values(c.initiator_id,c.id,now()),(c.recipient_id,c.id,now()) on conflict on constraint market_inbox_events_pkey do update set updated_at=clock_timestamp(); return new; end $$;
create trigger market_message_event after insert on private.market_messages for each row execute function private.market_message_event();
create function public.market_chat_request(profile_id text,intro text) returns uuid language plpgsql security definer set search_path='' as $$ declare u uuid:=private.market_account(); recipient uuid; cid uuid; begin
 if intro is null or length(trim(intro)) not between 1 and 2000 then raise exception 'Introduction must be 1–2000 characters'; end if;
 select o.user_id into recipient from private.talent_owners o join public.talent_profiles p on p.id=o.profile_id where o.profile_id=market_chat_request.profile_id and p.published;
 if recipient is null or recipient=u then raise exception 'An approved claimed profile belonging to another member is required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,6007));
 perform pg_advisory_xact_lock(hashtextextended(least(u,recipient)::text||greatest(u,recipient)::text,6006));
 select id into cid from private.market_conversations where kind='direct' and least(initiator_id,recipient_id)=least(u,recipient) and greatest(initiator_id,recipient_id)=greatest(u,recipient);
 if cid is not null then return cid; end if;
 if (select count(*) from private.market_conversations where initiator_id=u and created_at>now()-interval '1 day')>=10 then raise exception 'Daily chat request limit reached'; end if;
 insert into private.market_conversations(kind,status,initiator_id,recipient_id) values('direct','pending',u,recipient) returning id into cid;
 insert into private.market_messages(conversation_id,sender_id,body,client_id) values(cid,u,trim(intro),gen_random_uuid()); return cid; end $$;
create function public.market_chat_respond(conversation_id uuid,action text) returns void language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); begin
 perform 1 from private.market_conversations where id=c.id for update;
 if action='block' then update private.market_conversations set status='blocked' where id=c.id;
 elsif action in ('accept','decline') and c.recipient_id=auth.uid() and c.status='pending' then update private.market_conversations set status=case action when 'accept' then 'active' else 'declined' end where id=c.id and status='pending';
 else raise exception 'Action unavailable'; end if; end $$;
create function private.market_project_conversation(project_id uuid,proposal_id uuid,buyer_id uuid,provider_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ #variable_conflict use_column
 declare cid uuid; begin
 perform pg_advisory_xact_lock(hashtextextended(project_id::text||buyer_id::text||provider_id::text,6010));
 select c.id into cid from private.market_conversations c where c.kind='project' and c.project_id=market_project_conversation.project_id and c.initiator_id=buyer_id and c.recipient_id=provider_id;
 if cid is not null then update private.market_conversations set proposal_id=market_project_conversation.proposal_id where id=cid; return cid; end if;
 insert into private.market_conversations(kind,status,initiator_id,recipient_id,project_id,proposal_id) values('project','active',buyer_id,provider_id,project_id,proposal_id) returning id into cid;
 return cid; end $$;
create function public.market_send_message(conversation_id uuid,body text,client_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare c private.market_conversations; result uuid; previous private.market_messages; begin
 c:=private.market_conversation_access(conversation_id); perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,6008)); perform 1 from private.market_conversations where id=c.id for update;
 select * into c from private.market_conversations where id=c.id;
 if c.status<>'active' then raise exception 'Conversation must be accepted and unblocked'; end if;
 if client_id is null or body is null or length(trim(body)) not between 1 and 10000 then raise exception 'Invalid message'; end if;
 select * into previous from private.market_messages m where m.sender_id=auth.uid() and m.client_id=market_send_message.client_id;
 if found then if previous.conversation_id<>c.id or previous.body<>trim(body) then raise exception 'Retry identifier conflict'; end if; return previous.id; end if;
 if (select count(*) from private.market_messages where sender_id=auth.uid() and created_at>now()-interval '1 minute')>=30 then raise exception 'Message rate limit reached'; end if;
 insert into private.market_messages(conversation_id,sender_id,body,client_id) values(c.id,auth.uid(),trim(body),client_id) returning id into result; return result; end $$;
create function public.market_conversations() returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.market_account(); begin return coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select c.*,coalesce((select p.data->>'name' from private.talent_owners o join public.talent_profiles p on p.id=o.profile_id where o.user_id=case when c.initiator_id=u then c.recipient_id else c.initiator_id end limit 1),'Member') as counterpart_name,(select count(*) from private.market_messages m where m.conversation_id=c.id and m.sender_id<>u and (m.created_at,m.id)>(coalesce((select r.read_at from private.market_read_positions r where r.conversation_id=c.id and r.user_id=u),'-infinity'),coalesce((select r.read_message_id from private.market_read_positions r where r.conversation_id=c.id and r.user_id=u),'00000000-0000-0000-0000-000000000000'::uuid))) as unread_count,(select m.body from private.market_messages m where m.conversation_id=c.id order by m.created_at desc limit 1) as last_body from private.market_conversations c where u in(c.initiator_id,c.recipient_id)) q),'[]'); end $$;
create function public.market_thread(conversation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); begin return jsonb_build_object('conversation',to_jsonb(c)||jsonb_build_object('counterpart_name',coalesce((select p.data->>'name' from private.talent_owners o join public.talent_profiles p on p.id=o.profile_id where o.user_id=case when c.initiator_id=auth.uid() then c.recipient_id else c.initiator_id end limit 1),'Member')),'messages',coalesce((select jsonb_agg(to_jsonb(m) order by m.created_at,m.id) from private.market_messages m where m.conversation_id=c.id),'[]'),'attachments',coalesce((select jsonb_agg(to_jsonb(a)-'object_path' order by a.created_at) from private.market_attachments a where a.conversation_id=c.id),'[]')); end $$;
create function public.market_mark_read(conversation_id uuid,last_message_id uuid default null) returns void language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); m private.market_messages; changed integer; begin
 if last_message_id is null then return; end if;
 select * into m from private.market_messages where id=last_message_id and private.market_messages.conversation_id=c.id;
 if not found then raise exception 'Displayed message does not belong to this conversation'; end if;
 insert into private.market_read_positions(conversation_id,user_id,read_at,read_message_id) values(c.id,auth.uid(),m.created_at,m.id) on conflict on constraint market_read_positions_pkey do update set read_at=excluded.read_at,read_message_id=excluded.read_message_id where (private.market_read_positions.read_at,coalesce(private.market_read_positions.read_message_id,'00000000-0000-0000-0000-000000000000'::uuid))<(excluded.read_at,excluded.read_message_id);
 get diagnostics changed=row_count; if changed=0 then return; end if;
 insert into public.market_inbox_events values(auth.uid(),c.id,clock_timestamp()) on conflict on constraint market_inbox_events_pkey do update set updated_at=clock_timestamp(); end $$;
create function public.market_report(conversation_id uuid,reason text) returns uuid language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); rid uuid; begin perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,6009)); if (select count(*) from private.market_reports where reporter_id=auth.uid() and created_at>now()-interval '1 day')>=10 then raise exception 'Daily report limit reached'; end if; if reason is null or length(trim(reason)) not between 10 and 4000 then raise exception 'Report requires 10–4000 characters'; end if; insert into private.market_reports(conversation_id,reporter_id,reason) values(c.id,auth.uid(),trim(reason)) returning id into rid; return rid; end $$;
create function public.market_message_preferences(email_enabled boolean) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.market_account(); begin insert into private.market_message_preferences values(u,email_enabled) on conflict(user_id) do update set email_enabled=excluded.email_enabled; if not email_enabled then delete from private.market_message_reminders where user_id=u and status='pending'; end if; end $$;
create function public.market_prepare_attachment(conversation_id uuid,filename text,content_type text,byte_size bigint) returns jsonb language plpgsql security definer set search_path='' as $$ declare c private.market_conversations:=private.market_conversation_access(conversation_id); aid uuid:=gen_random_uuid(); path text; ext text; begin
 perform 1 from private.market_conversations where id=c.id for update; select * into c from private.market_conversations where id=c.id;
 if c.status<>'active' then raise exception 'Accepted conversation required'; end if;
 if (select count(*) from private.market_attachments where uploader_id=auth.uid() and created_at>now()-interval '1 day')>=100 then raise exception 'Daily file limit reached'; end if;
 ext:=lower(substring(filename from '\.([^.]+)$'));
 if filename is null or length(filename) not between 1 and 200 or filename ~ '[/\\]' or ext is null or ext not in('png','jpg','jpeg','webp','pdf','txt','csv','docx','xlsx','pptx','step','stp','stl','iges','igs','dxf','dwg','fcstd','kicad_pcb','kicad_sch','zip') or byte_size is null or byte_size not between 1 and 52428800 or content_type is null or content_type not in ('image/png','image/jpeg','image/webp','application/pdf','text/plain','text/csv','application/zip','application/octet-stream','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation') then raise exception 'Unsupported file or exceeds 50 MB'; end if;
 path:=c.id::text||'/'||aid::text;
 insert into private.market_attachments(id,conversation_id,uploader_id,filename,content_type,byte_size,object_path) values(aid,c.id,auth.uid(),filename,content_type,byte_size,path);
 return jsonb_build_object('id',aid,'object_path',path,'status','quarantined'); end $$;
create function public.market_attachment_access(attachment_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare a private.market_attachments; c private.market_conversations; begin select * into a from private.market_attachments where id=attachment_id; if not found then raise exception 'File unavailable'; end if; c:=private.market_conversation_access(a.conversation_id); if c.status<>'active' or a.status<>'clean' then raise exception 'File unavailable until scanning succeeds'; end if; return jsonb_build_object('object_path',a.object_path,'filename',a.filename,'content_type',a.content_type); end $$;
create function public.market_case_thread(report_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.talent_require_account(); cid uuid; begin if not exists(select 1 from private.market_case_reviewers r where r.report_id=market_case_thread.report_id and r.reviewer_id=u) then raise exception 'Case assignment required' using errcode='42501'; end if; select conversation_id into cid from private.market_reports where id=report_id; insert into private.market_case_access(report_id,reviewer_id) values(report_id,u); return jsonb_build_object('messages',coalesce((select jsonb_agg(to_jsonb(m) order by created_at) from private.market_messages m where conversation_id=cid),'[]')); end $$;
create function private.market_queue_reminders() returns integer language plpgsql security definer set search_path='' as $$ declare n integer; begin
 insert into private.market_message_reminders(user_id,unread_count)
 select e.user_id,count(*) from public.market_inbox_events e join private.market_conversations c on c.id=e.conversation_id join private.market_messages m on m.conversation_id=c.id and m.sender_id<>e.user_id left join private.market_read_positions r on r.conversation_id=c.id and r.user_id=e.user_id left join private.market_message_preferences p on p.user_id=e.user_id where c.status in('pending','active') and coalesce(p.email_enabled,true) and (m.created_at,m.id)>(coalesce(r.read_at,'-infinity'),coalesce(r.read_message_id,'00000000-0000-0000-0000-000000000000'::uuid)) and m.created_at<now()-interval '15 minutes' group by e.user_id
 on conflict(user_id) do update set unread_count=excluded.unread_count,status='pending',queued_at=now(),last_queued_at=now() where private.market_message_reminders.last_queued_at<now()-interval '1 day'; get diagnostics n=row_count; return n; end $$;
DO $$ declare f record; begin for f in select p.oid::regprocedure as signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname = any(array['market_account','market_conversation_access','market_message_event','market_chat_request','market_chat_respond','market_project_conversation','market_send_message','market_conversations','market_thread','market_mark_read','market_report','market_message_preferences','market_prepare_attachment','market_attachment_access','market_case_thread','market_queue_reminders']) loop execute format('revoke all on function %s from public,anon,authenticated',f.signature); if f.nspname='public' then execute format('grant execute on function %s to authenticated',f.signature); end if; end loop; end $$;
DO $$ begin if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='market_inbox_events') then alter publication supabase_realtime add table public.market_inbox_events; end if; end $$;

create function public.market_attachment_scan_result(attachment_id uuid,clean boolean) returns void language plpgsql security definer set search_path='' as $$ begin update private.market_attachments set status=case when clean then 'clean' else 'rejected' end where id=attachment_id and status='quarantined'; end $$;
revoke all on function public.market_attachment_scan_result(uuid,boolean) from public,anon,authenticated;
grant execute on function public.market_attachment_scan_result(uuid,boolean) to service_role;
DO $$ begin if to_regclass('storage.buckets') is not null then insert into storage.buckets(id,name,public,file_size_limit) values('market-files','market-files',false,52428800) on conflict(id) do nothing; end if; end $$;
create trigger market_attachment_event after insert or update of status on private.market_attachments for each row execute function private.market_message_event();
create function private.market_conversation_event() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.market_inbox_events values(new.initiator_id,new.id,clock_timestamp()),(new.recipient_id,new.id,clock_timestamp()) on conflict on constraint market_inbox_events_pkey do update set updated_at=clock_timestamp(); return new; end $$;
revoke all on function private.market_conversation_event() from public,anon,authenticated;
create trigger market_conversation_event after insert or update of status on private.market_conversations for each row execute function private.market_conversation_event();

create function public.market_get_message_preferences() returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.market_account(); begin return jsonb_build_object('email_enabled',coalesce((select email_enabled from private.market_message_preferences where user_id=u),true)); end $$;
revoke all on function public.market_get_message_preferences() from public,anon;
grant execute on function public.market_get_message_preferences() to authenticated;
